+fn with_boss() -> State {
+    let mut state = State::new();
+    state.history.execute(&state.world, ImportModel::from_mesh("boss", cylinder(20.0, 10.0, 48)));
+    state.viewport_rect = ([0.0, 0.0], [400.0, 400.0]);
